from pathlib import Path
import base64,hashlib,json,os,subprocess,sys,time
repo=Path('/workspace/p2-saving16-20261125')
stage=Path('/workspace/p25-round18-preflight-20261127')
expected='57667adb2b19ebc700bd63b2fa975f2c06dab1788a37044d3e85ed90c8c9c30a'
source=base64.b64decode('',validate=True)
assert hashlib.sha256(source).hexdigest()==expected
assert subprocess.check_output(['git','rev-parse','HEAD'],cwd=repo,text=True).strip()=='f0c80794844b7a1318eb386ce454988af1c678a3'
terminal=json.loads((repo/'.lake/p25-followup-repairs-attempt017/RUN_RESULT.json').read_bytes())
checks={k:v for k,v in terminal.items() if k.endswith('_after_matches')}
assert terminal['ended_utc'] and len(checks)==9 and all(x is True for x in checks.values())
assert terminal['audit_summary']['modules']['ImbalancedChen.P4AOriginalAscendingCell0Literal96']['accepted'] is True
stage.mkdir(exist_ok=False)
target=stage/'ImbalancedChen/P4AOriginalCell0AffineChronology.lean'
target.parent.mkdir()
target.write_bytes(source)
sys.path.insert(0,str(repo/'verification/part2'))
from winner9_external_snapshot import ExternalSnapshot
from run_winner9_private_checks import PIN,LEAN
external=ExternalSnapshot(Path(terminal['external_after']['snapshot']),lean=LEAN,mathlib_pin=PIN,project_lib=repo/'.lake/p2-private/lib')
before=external.verify()
assert before==terminal['external_after']
env=external.environment(os.environ)
cmd=[LEAN,'-t0','-j1','-M11264','-DwarningAsError=true','-DmaxRecDepth=50000','-DmaxHeartbeats=40000000','--root='+str(stage),'-o',str(target.with_suffix('.olean')),str(target)]
start=time.monotonic()
with (stage/'NORMAL.log').open('wb') as log:
    process=subprocess.run(cmd,cwd=stage,env=env,stdout=log,stderr=subprocess.STDOUT,timeout=1000)
result={'schema':'p25-round18-normal-only-preflight-v1','source_sha256':expected,'exit_code':process.returncode,'elapsed_seconds':time.monotonic()-start,'command':cmd,'external_before':before,'external_after_matches':external.verify()==before,'source_after_matches':hashlib.sha256(target.read_bytes()).hexdigest()==expected,'log_sha256':hashlib.sha256((stage/'NORMAL.log').read_bytes()).hexdigest(),'scope':'Normal preflight only. No main-closure, replay, or owned acceptance is asserted.'}
(stage/'RESULT.json').write_text(json.dumps(result,sort_keys=True,indent=2)+'\n')
print(json.dumps({k:v for k,v in result.items() if k!='external_before'},indent=2))
print((stage/'NORMAL.log').read_text()[-30000:])
sys.exit(process.returncode)
